INSERT INTO news (title, body, snippet, source_url, source_name, published_at, sort_order) SELECT 'Irish Sport Horses win 5 classes including 2 CCIs at the GMH Festival', 'Martin Crowley’s Crossfield Lass breeds two Top 10 Places at Open Preliminary. OBOS Quality has 7 mentions but only one as a Dam’s Sire and TIH get 17 mentions.

